        var waterTemperature: API.WaterTemperature?

        /// `brew_time_s`.
        var brewTimeS: API.BrewTimeS?

        /// `grind_normalised`.
        var grindNormalised: API.GrindNormalised?

        /// `water_type`.
        var waterType: Vocabulary.WaterType?

        /// `milk`.
        var milk: Vocabulary.MilkType?

        init(
            method: Vocabulary.Method,
            doseDg: API.DoseDg? = nil,
            waterG: API.WaterG? = nil,
            waterTemperature: API.WaterTemperature? = nil,
            brewTimeS: API.BrewTimeS? = nil,
            grindNormalised: API.GrindNormalised? = nil,
            waterType: Vocabulary.WaterType? = nil,
            milk: Vocabulary.MilkType? = nil
        ) {
            self.method = method
            self.doseDg = doseDg
            self.waterG = waterG
            self.waterTemperature = waterTemperature
            self.brewTimeS = brewTimeS
            self.grindNormalised = grindNormalised
            self.waterType = waterType
            self.milk = milk
        }

        enum CodingKeys: String, CodingKey {
            case method = "method"
            case doseDg = "dose_dg"
            case waterG = "water_g"
            case waterTempC = "water_temp_c"
            case waterTempSpecial = "water_temp_special"
            case brewTimeS = "brew_time_s"
            case grindNormalised = "grind_normalised"
            case waterType = "water_type"
            case milk = "milk"
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.method = try container.decode(Vocabulary.Method.self, forKey: .method)
            self.doseDg = try container.decodeIfPresent(API.DoseDg.self, forKey: .doseDg)
            self.waterG = try container.decodeIfPresent(API.WaterG.self, forKey: .waterG)
            var waterTemperatureValues: [API.WaterTemperature] = []
            if let value = try container.decodeIfPresent(API.WaterTempC.self, forKey: .waterTempC) {
                waterTemperatureValues.append(.celsius(value))
            }
            if let value = try container.decodeIfPresent(Vocabulary.WaterTempSpecial.self, forKey: .waterTempSpecial) {
                waterTemperatureValues.append(.special(value))
            }
            guard waterTemperatureValues.count <= 1 else {
                throw DecodingError.dataCorruptedError(
                    forKey: .waterTempSpecial,
                    in: container,
                    debugDescription: "water_temp_c and water_temp_special exclude each other."
                )
            }
            self.waterTemperature = waterTemperatureValues.first
            self.brewTimeS = try container.decodeIfPresent(API.BrewTimeS.self, forKey: .brewTimeS)
            self.grindNormalised = try container.decodeIfPresent(API.GrindNormalised.self, forKey: .grindNormalised)
            self.waterType = try container.decodeIfPresent(Vocabulary.WaterType.self, forKey: .waterType)
            self.milk = try container.decodeIfPresent(Vocabulary.MilkType.self, forKey: .milk)
        }

        func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(method, forKey: .method)
            try container.encodeIfPresent(doseDg, forKey: .doseDg)
            try container.encodeIfPresent(waterG, forKey: .waterG)
            if let value = self.waterTemperature {
                switch value {
                case .celsius(let member):
                    try container.encode(member, forKey: .waterTempC)
                case .special(let member):
                    try container.encode(member, forKey: .waterTempSpecial)
                }
            }
            try container.encodeIfPresent(brewTimeS, forKey: .brewTimeS)
            try container.encodeIfPresent(grindNormalised, forKey: .grindNormalised)
            try container.encodeIfPresent(waterType, forKey: .waterType)
            try container.encodeIfPresent(milk, forKey: .milk)
        }

        /// `dose_dg` in the unit of brew.ranges.dose_g (scale 10, ADR 0004).
        /// Setting it rounds to the nearest 1/10; a value that is not finite clears `doseDg`.
        var doseGrams: Double? {
            get { doseDg.map { value in Double(value) / 10 } }
            set { doseDg = newValue.flatMap { value in API.scaledInteger(value, scale: 10) } }
        }
    }

